def count_subseq_with_sum(arr, k):
    n = len(arr)

    def dfs(i, remaining):
        if i == n:
            return 1 if remaining == 0 else 0
        pick = dfs(i + 1, remaining - arr[i])
        skip = dfs(i + 1, remaining)
        return pick + skip

    return dfs(0, k)

