class QueueUsingStacks:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def enqueue(self, x):
        self.inbox.append(x)

    def _pour(self):
        while self.inbox:
            self.outbox.append(self.inbox.pop())

    def dequeue(self):
        if not self.outbox:
            self._pour()
        return self.outbox.pop() if self.outbox else None

    def front(self):
        if not self.outbox:
            self._pour()
        return self.outbox[-1] if self.outbox else None

