class StackUsingQueue:
    # push-costly variant: pop and top are O(1)
    def __init__(self):
        self.q = deque()

    def push(self, x):
        self.q.append(x)
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())   # rotate old elements behind x

    def pop(self):
        return self.q.popleft() if self.q else None

    def top(self):
        return self.q[0] if self.q else None

