def build_from_level_order(values):
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    i = 1
    while queue and i < len(values):
        node = queue.popleft()
        if i < len(values) and values[i] is not None:
            node.left = TreeNode(values[i])
            queue.append(node.left)
        i += 1
        if i < len(values) and values[i] is not None:
            node.right = TreeNode(values[i])
            queue.append(node.right)
        i += 1
    return root

def search_bst(root, target):
    node = root
    while node is not None:
        if target == node.data:
            return node
        node = node.left if target < node.data else node.right
    return None

def insert_bst(root, x):
    if root is None:
        return TreeNode(x)
    node = root
    while True:
        if x < node.data:
            if node.left is None:
                node.left = TreeNode(x)
                return root
            node = node.left
        elif x > node.data:
            if node.right is None:
                node.right = TreeNode(x)
                return root
            node = node.right
        else:
            return root    # already present

def heapify_down(heap, i):
    n = len(heap)
    while True:
        smallest = i
        l, r = 2 * i + 1, 2 * i + 2
        if l < n and heap[l] < heap[smallest]:
            smallest = l
        if r < n and heap[r] < heap[smallest]:
            smallest = r
        if smallest == i:
            break
        heap[i], heap[smallest] = heap[smallest], heap[i]
        i = smallest

def push(heap, x):
