def insert(root, num):
    node = root
    for b in range(MAX_BIT, -1, -1):
        bit = (num >> b) & 1
        if node.child[bit] is None:
            node.child[bit] = BitTrieNode()
        node = node.child[bit]
        node.count += 1

def max_xor_with(root, x):
    node = root
    best = 0
    for b in range(MAX_BIT, -1, -1):
        bit = (x >> b) & 1
        want = 1 - bit
        if node.child[want] is not None:
            best |= (1 << b)        # this answer bit becomes 1
            node = node.child[want]
        else:
            node = node.child[bit]
    return best

